      beforeMark₀ beforeMark₁ beforeMark₂ beforeMark₃ : SOGroup m}
    {beforeLocal₁ : Path beforeMark₁ beforeMark₀}
    {beforeLocal₂ : Path beforeMark₃ beforeMark₂}
    {afterBand₁ : Path afterMark₁ afterMark₂}
    {afterBand₂ : Path afterMark₃ afterMark₀}
    {connector₀ : Path beforeMark₀ afterMark₀}
    {connector₁ : Path beforeMark₁ afterMark₁}
    {connector₂ : Path beforeMark₂ afterMark₂}
    {connector₃ : Path beforeMark₃ afterMark₃}
    (R : SaddleBandWindingRealization beforeLocal₁ beforeLocal₂
      afterBand₁ afterBand₂ connector₀ connector₁ connector₂ connector₃) :
    ∃ (U V : SOGroup m) (θ : C(I, ℝ)) (k : ℤ), Odd k ∧
      θ 1 = θ 0 + 2 * Real.pi * k ∧
      ∀ t : I,
        (((beforeLocal₁.symm.trans connector₁).trans
            (afterBand₁.trans connector₂.symm)).trans
          ((beforeLocal₂.symm.trans connector₃).trans
            (afterBand₂.trans connector₀.symm))) t
          = so2Coset U V (θ t)

